"use strict";
import { useMemo } from "react";
import { useModalState } from "hooks/useModalState";
import { useManagedDeposits } from "hooks/useManagedDeposits";
import { useVeABXUserLocks } from "hooks/useVeABXLocks";
import { useVotedLocks } from "hooks/useVotedLocks";
import { useVeABXRebaseClaimables } from "hooks/useVeABXRebaseClaimables";
import TokenomicsModal from "pages/Dash/components/TokenomicsModal";
import { Flex, Text } from "ui/src";
import { QuestionInCircle } from "ui/src/components/icons";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { ModalName } from "uniswap/src/features/telemetry/constants";
import { useAccount, useChainId } from "wagmi";
import LoackLoader from "./LoackLoader";
import SingleLock from "./SingleLock";
export default function Locks() {
  const { toggleModal: toggleTokenomicsModal } = useModalState(ModalName.Tokenomics);
  const { address: account } = useAccount();
  const rawChainId = useChainId();
  const resolvedChainId = useMemo(() => {
    if (rawChainId === UniverseChainId.Mainnet || rawChainId === UniverseChainId.Sepolia) {
      return rawChainId;
    }
    return UniverseChainId.Mainnet;
  }, [rawChainId]);
  const {
    data: userLocks = [],
    isLoading: locksLoading,
    error: locksError
  } = useVeABXUserLocks(account, true, resolvedChainId);
  const {
    depositMap,
    isLoading: depositsLoading
  } = useManagedDeposits(userLocks || []);
  const { hasVoted } = useVotedLocks(userLocks || []);
  const standaloneLocks = useMemo(
    () => (userLocks || []).filter((lock) => {
      const managedInfo = depositMap.get(lock.id);
      return !(managedInfo?.isDeposited && managedInfo.managedTokenId);
    }),
    [userLocks, depositMap]
  );
  const standaloneLockIds = useMemo(() => standaloneLocks.map((lock) => lock.id), [standaloneLocks]);
  const {
    claimableMap: rebaseClaimableMap,
    isLoading: rebaseLoading,
    isFetching: rebaseFetching,
    refetch: refetchRebaseClaimables
  } = useVeABXRebaseClaimables(standaloneLockIds, resolvedChainId);
  const isRebaseLoading = rebaseLoading || rebaseFetching;
  const isDataLoading = locksLoading || depositsLoading;
  const renderLocks = () => {
    if (isDataLoading) {
      return Array.from({ length: 3 }, (_, index) => <LoackLoader key={`lock-skeleton-${index}`} />);
    }
    if (locksError) {
      return <Flex centered py="$spacing40">
          <Text variant="body3" color="$statusCritical">
            Failed to load locks
          </Text>
        </Flex>;
    }
    if (!account) {
      return <Flex centered py="$spacing40">
          <Text variant="body3" color="$neutral2">
            Connect wallet to view your locks
          </Text>
        </Flex>;
    }
    if (standaloneLocks.length === 0) {
      return <Flex centered py="$spacing40">
          <Text variant="body3" color="$neutral2">
            No standalone locks found. Manage your deposited positions in the ABX Vaults section below.
          </Text>
        </Flex>;
    }
    return standaloneLocks.map((lock) => {
      const managedInfo = depositMap.get(lock.id);
      const claimableRebase = rebaseClaimableMap.get(lock.id);
      return <SingleLock
        key={lock.id}
        lock={lock}
        hasVoted={hasVoted(lock.id)}
        managedDeposit={managedInfo}
        isRelayActionPending={false}
        rebaseClaimable={claimableRebase}
        isRebaseLoading={isRebaseLoading}
        refreshRebaseClaimables={refetchRebaseClaimables}
      />;
    });
  };
  return <Flex marginTop={"$spacing36"}>
      <Flex className="top" row gap={"$spacing8"} alignItems="center">
        <Text variant={"heading3"}>Locks before fix styles</Text>
        <Flex height={17} onPress={toggleTokenomicsModal}>
          <QuestionInCircle
    color={"$neutral2"}
    cursor="pointer"
    hoverStyle={{ color: "$neutral3" }}
    size={"$icon.20"}
  />
        </Flex>
      </Flex>

      <Flex className="locks" mt={"$spacing24"} flexDirection="column" gap={"$gap24"}>
        {renderLocks()}
      </Flex>
      <TokenomicsModal />
    </Flex>;
}
